//! Sine window tables

pub use crate::common::enums::WindowShape;
use num_complex::Complex;

pub fn get_table(length: u16, shape: WindowShape) -> Option<&'static [Complex<f32>]> {
    // Get ld2 of length - 2 + 1
    // -2: because first table entry is window of size 4
    // +1: because we already include +1 because of ceil(log2(length))
    let ld2_length = (u16::BITS - 1 - length.leading_zeros() - 2 + 1) as usize;

    let mut index = ld2_length;
    if shape == WindowShape::KBD {
        // The table for KBD windows is 4 entries shorter.
        index -= 4;
    };

    let this_shape = if shape == WindowShape::LowOverlap {
        // Use Sine Tables for LD.
        WindowShape::Sine
    } else {
        shape
    };

    // Return table according to table type
    match (length) >> (ld2_length - 1) {
        0x4 => WINDOW_SLOPES[this_shape as usize][0][index - 1], // radix 2
        0x7 => WINDOW_SLOPES[this_shape as usize][1][index],     // 10 ms
        0x6 => WINDOW_SLOPES[this_shape as usize][2][index],     // 3/4 of radix 2
        0x5 => WINDOW_SLOPES[this_shape as usize][3][index],     // 5/16 of radix 2
        _ => None,
    }
}

